import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import reservationService from '../../services/reservationService';
import authService from '../../services/authService';
import PageHeader from '../../components/common/PageHeader';
import '../../components/common/shared.css';
import './BookingPage.css';

const diffDays = (a, b) => {
  if (!a || !b) return 0;
  return Math.max(0, Math.round((new Date(b) - new Date(a)) / 86400000));
};

const BookingPage = () => {
  const { state } = useLocation();
  const navigate  = useNavigate();
  const room      = state?.room;

  const [form, setForm] = useState({
    check_in:  state?.checkIn  || '',
    check_out: state?.checkOut || '',
    guests:    1,
    notes:     '',
  });
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState('');
  const [success, setSuccess]   = useState(false);

  // ✅ FIX : récupérer le client_id de l'utilisateur connecté
  // Le backend CreateReservationRequest exige clientId @NotNull
  const [clientId, setClientId] = useState(null);

  useEffect(() => {
    // Chercher d'abord dans localStorage (évite un appel réseau)
    try {
      const stored = localStorage.getItem('hotel_user');
      if (stored) {
        const u = JSON.parse(stored);
        // ⚠️ Selon ton backend, l'user peut avoir .clientId ou .id
        // Si l'entité User a une relation avec Client, adapte ici
        setClientId(u.clientId ?? u.id);
        return;
      }
    } catch (_) {}

    // Sinon appel API /auth/me
    authService.me()
      .then(u => setClientId(u.clientId ?? u.id))
      .catch(() => {});
  }, []);

  if (!room) {
    return (
      <div className="booking-no-room">
        <p>Aucune chambre sélectionnée.</p>
        <button className="btn btn--primary" onClick={() => navigate('/client/rooms')}>
          ← Voir les chambres
        </button>
      </div>
    );
  }

  const pricePerNight = room.price_per_night ?? room.price ?? 0;
  const nights = diffDays(form.check_in, form.check_out);
  const total  = nights * pricePerNight;

  const handleChange = ({ target: { name, value } }) =>
    setForm(p => ({ ...p, [name]: value }));

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.check_in || !form.check_out) {
      setError('Veuillez sélectionner vos dates.');
      return;
    }
    if (nights < 1) {
      setError("La date de départ doit être après la date d'arrivée.");
      return;
    }
    // ✅ FIX : vérifier que le clientId est disponible
    if (!clientId) {
      setError('Impossible de récupérer votre identifiant client. Veuillez vous reconnecter.');
      return;
    }

    setLoading(true);
    setError('');
    try {
      await reservationService.create({
        // ✅ FIX : client_id obligatoire — mappé vers clientId dans reservationService
        client_id: clientId,
        room_id:   room.id,
        check_in:  form.check_in,
        check_out: form.check_out,
        guests:    form.guests,
        notes:     form.notes,
      });
      setSuccess(true);
      setTimeout(() => navigate('/client/reservations'), 2000);
    } catch (err) {
      const msg =
        err?.response?.data?.message ||
        err?.response?.data?.error   ||
        err?.message                 ||
        'Erreur lors de la réservation';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="booking-success">
        <span className="booking-success__icon">✓</span>
        <h3>Réservation confirmée !</h3>
        <p>Redirection vers vos réservations…</p>
      </div>
    );
  }

  return (
    <div>
      <PageHeader
        title="Réserver une chambre"
        subtitle={`Chambre ${room.number} — ${room.type}`}
        action={
          <button className="btn btn--outline" onClick={() => navigate(-1)}>
            ← Retour
          </button>
        }
      />

      <div className="booking-layout">
        <form className="booking-form" onSubmit={handleSubmit}>
          {error && <div className="booking-error">{error}</div>}

          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Date d'arrivée *</label>
              <input
                type="date"
                name="check_in"
                className="form-input"
                value={form.check_in}
                min={new Date().toISOString().split('T')[0]}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Date de départ *</label>
              <input
                type="date"
                name="check_out"
                className="form-input"
                value={form.check_out}
                min={
                  form.check_in
                    ? new Date(new Date(form.check_in).getTime() + 86400000).toISOString().split('T')[0]
                    : new Date().toISOString().split('T')[0]
                }
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Nombre de personnes</label>
            <input
              type="number"
              name="guests"
              className="form-input"
              value={form.guests}
              min={1}
              max={room.capacity ?? 4}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Remarques</label>
            <textarea
              name="notes"
              className="form-textarea"
              value={form.notes}
              onChange={handleChange}
              placeholder="Demandes particulières, heure d'arrivée estimée…"
            />
          </div>

          <div className="form-actions">
            <button
              type="submit"
              className="btn btn--gold"
              disabled={loading || nights < 1 || !clientId}
            >
              {loading
                ? <span className="dt-spinner" />
                : `Confirmer la réservation${total ? ` — ${total} €` : ''}`
              }
            </button>
          </div>
        </form>

        <aside className="booking-summary">
          <h3 className="booking-summary__title">Récapitulatif</h3>
          <div className="booking-summary__row">
            <span>Chambre</span>
            <strong>{room.number}</strong>
          </div>
          <div className="booking-summary__row">
            <span>Type</span>
            <strong>{room.type?.toUpperCase?.() ?? room.type}</strong>
          </div>
          <div className="booking-summary__row">
            <span>Prix / nuit</span>
            <strong>{pricePerNight ? `${pricePerNight} €` : '—'}</strong>
          </div>
          <div className="booking-summary__row">
            <span>Nuits</span>
            <strong>{nights || '—'}</strong>
          </div>
          <div className="booking-summary__divider" />
          <div className="booking-summary__total">
            <span>Total estimé</span>
            <strong>{total ? `${total} €` : '—'}</strong>
          </div>
        </aside>
      </div>
    </div>
  );
};

export default BookingPage;
